  INSERT INTO projects (id, slug, name, description, status, epistemic_status, epistemic_status_note, hosting_mode, is_private, maturity, parent_project_id, focus_type, region_tags, theme_tags, working_languages)
    INSERT INTO project_members (project_id, user_id, role) VALUES (v_project, v_user, 'owner') ON CONFLICT (project_id, user_id) DO NOTHING;
  INSERT INTO project_source_declarations (project_id, source_name, format, license_or_rights_note, access_tier, url)
  INSERT INTO project_source_declarations (project_id, source_name, format, license_or_rights_note, access_tier, url)
  INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status) VALUES
  ('e4a76f03-c5c7-567c-ba76-3deaad6c5dc1', v_project, v_branch, 'concept', $J$Patterns$J$, $J$Noticing patterns in nature and using them to sort things, describe events and look for causes. Possible German counterpart (a hypothesis that needs an expert): none found. The name comes from NGSS. The wording is ours. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"e4a76f03-c5c7-567c-ba76-3deaad6c5dc1","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"ngss-crosscutting-concept","kind":"basic-concept","german_counterpart_hypothesis":"none found","review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The name is one of the seven NGSS crosscutting concepts. The plain wording and the German counterpart are our guesses."}}$J$::jsonb, 'proposed'),
  ('b23510e6-ff1d-5529-969e-ef072243ffbb', v_project, v_branch, 'concept', $J$Cause and Effect$J$, $J$Looking for what causes an event, how the cause leads to the effect, and whether a link is a cause or a coincidence. Possible German counterpart (a hypothesis that needs an expert): none found. The name comes from NGSS. The wording is ours. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"b23510e6-ff1d-5529-969e-ef072243ffbb","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"ngss-crosscutting-concept","kind":"basic-concept","german_counterpart_hypothesis":"none found","review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The name is one of the seven NGSS crosscutting concepts. The plain wording and the German counterpart are our guesses."}}$J$::jsonb, 'proposed'),
  ('9b7dd4f9-1d27-5b89-baac-095f7ac2b0f7', v_project, v_branch, 'concept', $J$Scale, Proportion, and Quantity$J$, $J$What a thing looks like and how it behaves can depend on its size, its time span and the amount of it. Possible German counterpart (a hypothesis that needs an expert): none found (the German list has system levels in its goal tags, which is a loose relative). The name comes from NGSS. The wording is ours. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"9b7dd4f9-1d27-5b89-baac-095f7ac2b0f7","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"ngss-crosscutting-concept","kind":"basic-concept","german_counterpart_hypothesis":"none found (the German list has system levels in its goal tags, which is a loose relative)","review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The name is one of the seven NGSS crosscutting concepts. The plain wording and the German counterpart are our guesses."}}$J$::jsonb, 'proposed'),
  ('dd55662f-2da0-5a80-952c-8122c1792b86', v_project, v_branch, 'concept', $J$Systems and System Models$J$, $J$Treating a set of parts that work together as a system, and using models to describe how its parts interact. Possible German counterpart (a hypothesis that needs an expert): none found (loosely related to the German system levels). The name comes from NGSS. The wording is ours. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"dd55662f-2da0-5a80-952c-8122c1792b86","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"ngss-crosscutting-concept","kind":"basic-concept","german_counterpart_hypothesis":"none found (loosely related to the German system levels)","review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The name is one of the seven NGSS crosscutting concepts. The plain wording and the German counterpart are our guesses."}}$J$::jsonb, 'proposed'),
  ('98067bb1-8aba-5e59-8853-d484b66dccf4', v_project, v_branch, 'concept', $J$Energy and Matter$J$, $J$Following energy and matter as they flow through a system and cycle within it. Possible German counterpart (a hypothesis that needs an expert): Stoff- und Energieumwandlung. The name comes from NGSS. The wording is ours. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"98067bb1-8aba-5e59-8853-d484b66dccf4","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"ngss-crosscutting-concept","kind":"basic-concept","german_counterpart_hypothesis":"Stoff- und Energieumwandlung","review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The name is one of the seven NGSS crosscutting concepts. The plain wording and the German counterpart are our guesses."}}$J$::jsonb, 'proposed'),
  ('9921adae-9c33-5bd7-a647-04aebb5c7249', v_project, v_branch, 'concept', $J$Structure and Function$J$, $J$How the shape and makeup of something relates to what it does. Possible German counterpart (a hypothesis that needs an expert): Struktur und Funktion. The name comes from NGSS. The wording is ours. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"9921adae-9c33-5bd7-a647-04aebb5c7249","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"ngss-crosscutting-concept","kind":"basic-concept","german_counterpart_hypothesis":"Struktur und Funktion","review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The name is one of the seven NGSS crosscutting concepts. The plain wording and the German counterpart are our guesses."}}$J$::jsonb, 'proposed'),
  ('897e80e3-388e-5ef9-9129-905c9e1c393a', v_project, v_branch, 'concept', $J$Stability and Change$J$, $J$What stays steady and what changes in a system, and why. Possible German counterpart (a hypothesis that needs an expert): Steuerung und Regelung, Individuelle Entwicklung and Evolutive Entwicklung (partly). The name comes from NGSS. The wording is ours. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"897e80e3-388e-5ef9-9129-905c9e1c393a","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"ngss-crosscutting-concept","kind":"basic-concept","german_counterpart_hypothesis":"Steuerung und Regelung, Individuelle Entwicklung and Evolutive Entwicklung (partly)","review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The name is one of the seven NGSS crosscutting concepts. The plain wording and the German counterpart are our guesses."}}$J$::jsonb, 'proposed'),
  ('10dbf53a-e6bf-59ac-a274-9f4512e8392a', v_project, v_branch, 'concept', $J$Evolution concepts$J$, $J$The concepts that evolution education researchers use to tag evolution content, as an English draft of the concept list in the German space EvoMentor Thuringia. The list has the same two levels as the German one, so the two spaces can be compared. How the evolution level of a goal is set: level 3 means the expectation text itself names evolution (the words evolution, evolutionary, coevolution or natural selection). Level 2 means it covers an evolution idea (variation, inheritance, differences in survival and reproduction, adaptation, common ancestry, fossils, deep time) without those words. Level 1 means background knowledge that evolution arguments build on. This rule is our draft and an expert should correct it. LLM synthesized draft, awaiting review.$J$, NULL, $J${"source_id":"10dbf53a-e6bf-59ac-a274-9f4512e8392a","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"evolution-concept-list-draft","kind":"evolution-lens","levels":{"1":"Background only","2":"Covers the idea without the word","3":"Names evolution explicitly"},"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. The English names are translated from the German list. Each concept shows its German original."}}$J$::jsonb, 'proposed')
  INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status) VALUES
  ('558ae4ad-88ed-55fb-af95-6084100d35d3', v_project, v_branch, 'concept', $J$Variation and diversity$J$, $J$Individuals in a population differ in their traits: in their genes, in how they look and in how they behave. This variation is the starting point for any form of selection and so for evolution. English name drafted from the German concept "Variation und Diversität". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_variation_diversitaet","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet","german_label":"Variation und Diversität","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Variation und Diversität\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('b9191283-dba0-550d-8736-0d1f1f3a309d', v_project, v_branch, 'concept', $J$Inheritance of traits$J$, $J$Traits pass from one generation to the next through several channels, some of them outside the genes. English name drafted from the German concept "Vererbung von Merkmalen". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_vererbung_merkmalen","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_vererbung_merkmalen","german_label":"Vererbung von Merkmalen","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Vererbung von Merkmalen\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('2b5c4785-a48c-5103-8a64-81747f862ab9', v_project, v_branch, 'concept', $J$Natural selection and selection pressure$J$, $J$Individuals with helpful traits survive and reproduce more often in a given environment. This difference in reproductive success drives change in populations over generations. English name drafted from the German concept "Natürliche Selektion und Selektionsdruck". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_natuerliche_selektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_natuerliche_selektion","german_label":"Natürliche Selektion und Selektionsdruck","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Natürliche Selektion und Selektionsdruck\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('4c794ae2-0229-5427-949e-2a58c8b27dc7', v_project, v_branch, 'concept', $J$Fitness$J$, $J$A measure of how much a genotype or phenotype contributes to the gene pool of the next generation through survival and reproduction. It differs from everyday physical fitness. English name drafted from the German concept "Fitness". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_fitness","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_fitness","german_label":"Fitness","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Fitness\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('2c0ad9ee-51fc-56a8-8920-bb28ba72a89d', v_project, v_branch, 'concept', $J$Adaptation and adaptedness$J$, $J$Traits that arose by natural selection because they raised survival or reproductive success in a particular environment. The pair of words covers the process (adaptation) and the result (adaptedness). English name drafted from the German concept "Anpassung und Angepasstheit". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_anpassung_angepasstheit","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_anpassung_angepasstheit","german_label":"Anpassung und Angepasstheit","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Anpassung und Angepasstheit\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('6c3b435d-f623-57f5-bf1f-c375b9320dcc', v_project, v_branch, 'concept', $J$Genetic drift$J$, $J$Random change in allele frequencies from one generation to the next, independent of any advantage. It acts most strongly in small populations. English name drafted from the German concept "Gendrift". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_gendrift","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_gendrift","german_label":"Gendrift","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Gendrift\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('a0e461e8-81fc-5c8f-b7b3-f6899e1b7a0f', v_project, v_branch, 'concept', $J$Migration and gene flow$J$, $J$Exchange of genetic material between populations when individuals move in or out. It works against differences between populations. English name drafted from the German concept "Migration/Genfluss". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_migration_genfluss","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_migration_genfluss","german_label":"Migration/Genfluss","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Migration/Genfluss\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('021510f2-b12f-5582-8f06-76c980ba7ec9', v_project, v_branch, 'concept', $J$Bottleneck effect$J$, $J$A sudden, strong drop in the genetic diversity of a population after an event that leaves only a small, unrepresentative part of it alive. English name drafted from the German concept "Flaschenhalseffekt". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_flaschenhalseffekt","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_flaschenhalseffekt","german_label":"Flaschenhalseffekt","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Flaschenhalseffekt\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('2a278d54-1c8e-5d7c-9a0a-1125be1191f3', v_project, v_branch, 'concept', $J$Founder effect$J$, $J$Lower genetic diversity in a newly founded population that descends from a small number of founders of a larger source population. English name drafted from the German concept "Gründereffekt". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_gruendereffekt","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_gruendereffekt","german_label":"Gründereffekt","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Gründereffekt\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('077378bf-7408-5614-b19f-8859a8302751', v_project, v_branch, 'concept', $J$Life history / life-history theory$J$, $J$Theory about how evolution shapes the timing of growth, reproduction and aging under limited resources, including the trade-off between the number of offspring and the investment in each. English name drafted from the German concept "Lebensgeschichte / Life-History-Theorie". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_lebensgeschichte","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_lebensgeschichte","german_label":"Lebensgeschichte / Life-History-Theorie","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Lebensgeschichte / Life-History-Theorie\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('cf023031-cec7-56dd-a042-97604581ec15', v_project, v_branch, 'concept', $J$Coevolution$J$, $J$Species adapt to each other over time. Changes in one species create selection pressure on the other. English name drafted from the German concept "Koevolution". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_koevolution","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_koevolution","german_label":"Koevolution","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Koevolution\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('ae76a609-b0ab-56b5-a8c0-7a373f577967', v_project, v_branch, 'concept', $J$Niche construction$J$, $J$Organisms change their environment and with it the conditions of selection for themselves and for other species. English name drafted from the German concept "Nischenkonstruktion". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_nischenkonstruktion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_nischenkonstruktion","german_label":"Nischenkonstruktion","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Nischenkonstruktion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('c29104e2-be2e-5fbd-b86d-f13f1a1f2b37', v_project, v_branch, 'concept', $J$Multilevel selection$J$, $J$Selection can act at several levels of biological organization at the same time, from genes and cells to individuals and groups. English name drafted from the German concept "Multilevel-Selektion". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_multilevel_selektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_multilevel_selektion","german_label":"Multilevel-Selektion","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Multilevel-Selektion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('6829faa3-1dcc-58ac-b0c4-e99af789b71a', v_project, v_branch, 'concept', $J$Deep time$J$, $J$The idea of the huge spans of Earth and life history, far beyond everyday experience, which make evolutionary change possible. English name drafted from the German concept "Tiefenzeit". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_tiefenzeit","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_tiefenzeit","german_label":"Tiefenzeit","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Tiefenzeit\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('7ab7367c-efc5-55db-921f-2ac8cd8e471a', v_project, v_branch, 'concept', $J$Phylogenetic trees and systematics$J$, $J$Diagrams and methods that show relationships between groups of organisms based on shared derived traits. English name drafted from the German concept "Stammbäume und phylogenetische Systematik". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_stammbaeume_phylogenetik","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_stammbaeume_phylogenetik","german_label":"Stammbäume und phylogenetische Systematik","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Stammbäume und phylogenetische Systematik\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('4d4af47c-f15e-5d35-bf70-94d39cbfeb94', v_project, v_branch, 'concept', $J$Conservation of traits (shared genetic basis, body plans, developmental processes and so on)$J$, $J$Basic genetic control mechanisms, body plans and developmental processes stay surprisingly similar over very long periods and across distant animal groups. English name drafted from the German concept "Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_konservierung_merkmalen","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_konservierung_merkmalen","german_label":"Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Konservierung von Merkmalen (gemeinsame genetische Grundlagen, Baupläne, Entwicklungsprozesse usw.)\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('b1bfa837-7840-5ebc-b988-ef604bb87cfb', v_project, v_branch, 'concept', $J$Homology and analogy / convergent and divergent evolution$J$, $J$Homologous structures go back to a shared pattern in an ancestor (divergent evolution). Analogous structures arose independently with a similar function (convergent evolution). English name drafted from the German concept "Homologie und Analogie/Konvergente und divergente Evolution". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_homologie_analogie","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_homologie_analogie","german_label":"Homologie und Analogie/Konvergente und divergente Evolution","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Homologie und Analogie/Konvergente und divergente Evolution\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('b07b24e5-b92b-5ae3-b57a-de5f2d19033b', v_project, v_branch, 'concept', $J$Speciation and adaptive radiation$J$, $J$The process by which one or more new species arise from an ancestral species, often through geographic isolation. Adaptive radiation is the quick split into many ecologically specialized species. English name drafted from the German concept "Artbildung und adaptive Radiation". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_artbildung_radiation","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_artbildung_radiation","german_label":"Artbildung und adaptive Radiation","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Artbildung und adaptive Radiation\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('e05d23c7-43b2-5a2c-ae5d-20884447e59d', v_project, v_branch, 'concept', $J$Extinction$J$, $J$The final disappearance of a species when no individual survives. It is a constant part of evolutionary history and speeds up during mass extinctions. English name drafted from the German concept "Aussterben". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_aussterben","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_aussterben","german_label":"Aussterben","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Aussterben\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('f1c3628c-6133-5771-8f26-b3da50b4cfed', v_project, v_branch, 'concept', $J$Evolutionary developmental biology (evo-devo)$J$, $J$A research field that asks how changes in the genetic programs of individual development lead to evolutionary changes in body plans. English name drafted from the German concept "Evolutionäre Entwicklungsbiologie (Evo-Devo)". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_evo_devo","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_evo_devo","german_label":"Evolutionäre Entwicklungsbiologie (Evo-Devo)","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Evolutionäre Entwicklungsbiologie (Evo-Devo)\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('69f1a651-e037-5376-af69-71a87febca95', v_project, v_branch, 'concept', $J$Cultural evolution$J$, $J$Change in knowledge, behavior, tools and social practices over generations through learning, transmission and selection among cultural variants. It resembles biological evolution but has mechanisms of its own. English name drafted from the German concept "kulturelle Evolution". LLM synthesized draft, awaiting review.$J$, '10dbf53a-e6bf-59ac-a274-9f4512e8392a', $J${"source_id":"ek_kulturelle_evolution","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_kulturelle_evolution","german_label":"kulturelle Evolution","level":1,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"kulturelle Evolution\" in the Thuringia space."}}$J$::jsonb, 'proposed')
  INSERT INTO lpm_schema_elements (id, project_id, branch_id, element_type, label, definition, parent_id, metadata, status) VALUES
  ('754a8c74-fb18-5e5b-a639-5ca0dc889f0e', v_project, v_branch, 'concept', $J$Genetic variation$J$, $J$Differences in the DNA sequence between individuals of a population. They arise through mutation, recombination and gene transfer. English name drafted from the German concept "genetische Variation". LLM synthesized draft, awaiting review.$J$, '558ae4ad-88ed-55fb-af95-6084100d35d3', $J${"source_id":"ek_variation_diversitaet__genetische_variation","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet__genetische_variation","german_label":"genetische Variation","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"genetische Variation\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('f6b8649b-89c4-5581-9e41-cbaeb30e0908', v_project, v_branch, 'concept', $J$Phenotypic variation$J$, $J$Visible differences in traits between individuals. They come from genetic variation, from the environment, or from both together. English name drafted from the German concept "phänotypische Variation". LLM synthesized draft, awaiting review.$J$, '558ae4ad-88ed-55fb-af95-6084100d35d3', $J${"source_id":"ek_variation_diversitaet__phaenotypische_variation","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet__phaenotypische_variation","german_label":"phänotypische Variation","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"phänotypische Variation\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('3287e6a6-8d18-5287-b61a-4d58c6883d81', v_project, v_branch, 'concept', $J$Modification$J$, $J$A change of the phenotype that is caused by the environment and is not inherited. It stays within the range that the genome allows. English name drafted from the German concept "Modifikation". LLM synthesized draft, awaiting review.$J$, '558ae4ad-88ed-55fb-af95-6084100d35d3', $J${"source_id":"ek_variation_diversitaet__modifikation","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet__modifikation","german_label":"Modifikation","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Modifikation\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('f05b98d0-bdef-5791-8f64-d952cca95394', v_project, v_branch, 'concept', $J$Recombination$J$, $J$New combinations of the parents' alleles during sexual reproduction (meiosis, crossing-over). It is a main source of genetic variation without new mutations. English name drafted from the German concept "Rekombination". LLM synthesized draft, awaiting review.$J$, '558ae4ad-88ed-55fb-af95-6084100d35d3', $J${"source_id":"ek_variation_diversitaet__rekombination","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet__rekombination","german_label":"Rekombination","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Rekombination\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('a20b5dc2-36cc-5507-b93b-6e2dbbaf3f56', v_project, v_branch, 'concept', $J$Gene transfer$J$, $J$Transfer of genetic material between organisms outside normal inheritance from parent to offspring (horizontal gene transfer). It matters most in bacteria. English name drafted from the German concept "Gentransfer". LLM synthesized draft, awaiting review.$J$, '558ae4ad-88ed-55fb-af95-6084100d35d3', $J${"source_id":"ek_variation_diversitaet__gentransfer","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet__gentransfer","german_label":"Gentransfer","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Gentransfer\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('630293aa-0e71-54d2-add6-d8d0e7ba58e3', v_project, v_branch, 'concept', $J$Epigenetics$J$, $J$Heritable changes in gene activity (for example through DNA methylation) that leave the DNA sequence itself unchanged. English name drafted from the German concept "Epigenetik". LLM synthesized draft, awaiting review.$J$, '558ae4ad-88ed-55fb-af95-6084100d35d3', $J${"source_id":"ek_variation_diversitaet__epigenetik","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet__epigenetik","german_label":"Epigenetik","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Epigenetik\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('b5ed4917-4cd4-51af-a486-10311a160cee', v_project, v_branch, 'concept', $J$Phenotypic plasticity$J$, $J$The ability of one genotype to produce different phenotypes under different environmental conditions. English name drafted from the German concept "Phänotypische Plastizität". LLM synthesized draft, awaiting review.$J$, '558ae4ad-88ed-55fb-af95-6084100d35d3', $J${"source_id":"ek_variation_diversitaet__phaenotypische_plastizitaet","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_variation_diversitaet__phaenotypische_plastizitaet","german_label":"Phänotypische Plastizität","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Phänotypische Plastizität\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('1dde3558-75d7-5d32-9ae5-5e7d034a23f0', v_project, v_branch, 'concept', $J$Genetic inheritance$J$, $J$Traits pass from parents to offspring through the DNA sequence. English name drafted from the German concept "genetische Vererbung". LLM synthesized draft, awaiting review.$J$, 'b9191283-dba0-550d-8736-0d1f1f3a309d', $J${"source_id":"ek_vererbung_merkmalen__genetische","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_vererbung_merkmalen__genetische","german_label":"genetische Vererbung","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"genetische Vererbung\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('93a18a2d-6bd5-59ab-9fa2-b9e2353941f3', v_project, v_branch, 'concept', $J$Epigenetic inheritance$J$, $J$Patterns of gene activity pass on over generations while the DNA sequence stays the same. English name drafted from the German concept "epigenetische Vererbung". LLM synthesized draft, awaiting review.$J$, 'b9191283-dba0-550d-8736-0d1f1f3a309d', $J${"source_id":"ek_vererbung_merkmalen__epigenetische","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_vererbung_merkmalen__epigenetische","german_label":"epigenetische Vererbung","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"epigenetische Vererbung\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('ede134f8-a31e-5615-90dc-8d36a37f7898', v_project, v_branch, 'concept', $J$Social and cultural inheritance$J$, $J$Behaviors, knowledge and skills pass on through watching, copying and teaching instead of through genes. English name drafted from the German concept "soziale/kulturelle Vererbung". LLM synthesized draft, awaiting review.$J$, 'b9191283-dba0-550d-8736-0d1f1f3a309d', $J${"source_id":"ek_vererbung_merkmalen__soziale_kulturelle","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_vererbung_merkmalen__soziale_kulturelle","german_label":"soziale/kulturelle Vererbung","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"soziale/kulturelle Vererbung\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('2983f3dc-abda-552f-ae1a-2279d2bf0b24', v_project, v_branch, 'concept', $J$Ecological inheritance$J$, $J$Offspring inherit an environment that their parents changed. This is a channel of inheritance next to the genes and is closely tied to niche construction. English name drafted from the German concept "ökologische Vererbung". LLM synthesized draft, awaiting review.$J$, 'b9191283-dba0-550d-8736-0d1f1f3a309d', $J${"source_id":"ek_vererbung_merkmalen__oekologische","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_vererbung_merkmalen__oekologische","german_label":"ökologische Vererbung","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"ökologische Vererbung\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('ee790278-1133-5426-b688-4a709f7a402f', v_project, v_branch, 'concept', $J$Stabilizing selection$J$, $J$Selection that disfavors extreme trait values and favors the middle of the range. English name drafted from the German concept "stabilisierende Selektion". LLM synthesized draft, awaiting review.$J$, '2b5c4785-a48c-5103-8a64-81747f862ab9', $J${"source_id":"ek_natuerliche_selektion__stabilisierende_selektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_natuerliche_selektion__stabilisierende_selektion","german_label":"stabilisierende Selektion","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"stabilisierende Selektion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('96b46efa-4592-5b52-9272-78d42ab82102', v_project, v_branch, 'concept', $J$Directional selection$J$, $J$Selection that favors one extreme of a trait and shifts the population average in one direction over generations. English name drafted from the German concept "gerichtete Selektion". LLM synthesized draft, awaiting review.$J$, '2b5c4785-a48c-5103-8a64-81747f862ab9', $J${"source_id":"ek_natuerliche_selektion__gerichtete_selektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_natuerliche_selektion__gerichtete_selektion","german_label":"gerichtete Selektion","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"gerichtete Selektion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('c318bb6b-0cf2-5e19-8188-0ebd2a372e2a', v_project, v_branch, 'concept', $J$Balancing selection$J$, $J$Selection that keeps genetic variation in a population, for example because individuals with two different alleles have an advantage. English name drafted from the German concept "balancierende Selektion". LLM synthesized draft, awaiting review.$J$, '2b5c4785-a48c-5103-8a64-81747f862ab9', $J${"source_id":"ek_natuerliche_selektion__balancierende_selektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_natuerliche_selektion__balancierende_selektion","german_label":"balancierende Selektion","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"balancierende Selektion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('fc0927d4-7250-5099-a052-15cff7dde339', v_project, v_branch, 'concept', $J$Frequency-dependent selection$J$, $J$How much a trait helps depends on how common it already is in the population. English name drafted from the German concept "frequenzabhängige Selektion". LLM synthesized draft, awaiting review.$J$, '2b5c4785-a48c-5103-8a64-81747f862ab9', $J${"source_id":"ek_natuerliche_selektion__frequenzabhaengige_selektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_natuerliche_selektion__frequenzabhaengige_selektion","german_label":"frequenzabhängige Selektion","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"frequenzabhängige Selektion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('43575e95-3f40-5027-ad11-d3907ced879f', v_project, v_branch, 'concept', $J$Trade-offs$J$, $J$Evolutionary compromises. A trait helps in one way and costs in another, so no trait can be best at everything at once. English name drafted from the German concept "Trade-offs/Zielkonflikte". LLM synthesized draft, awaiting review.$J$, '2b5c4785-a48c-5103-8a64-81747f862ab9', $J${"source_id":"ek_natuerliche_selektion__trade_offs","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_natuerliche_selektion__trade_offs","german_label":"Trade-offs/Zielkonflikte","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Trade-offs/Zielkonflikte\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('44118148-eba7-59c9-911d-d50452cb478a', v_project, v_branch, 'concept', $J$Sexual selection$J$, $J$Selection through differences in mating success that come from mate choice or from competition for mates, whatever the effect on survival. English name drafted from the German concept "sexuelle Selektion". LLM synthesized draft, awaiting review.$J$, '2b5c4785-a48c-5103-8a64-81747f862ab9', $J${"source_id":"ek_natuerliche_selektion__sexuelle_selektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_natuerliche_selektion__sexuelle_selektion","german_label":"sexuelle Selektion","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"sexuelle Selektion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('2defafc7-a089-5ddb-9d01-96a7f8ffed2e', v_project, v_branch, 'concept', $J$Function of traits$J$, $J$The job a trait does for its bearer, which selection can explain. English name drafted from the German concept "Funktion von Merkmalen". LLM synthesized draft, awaiting review.$J$, '2c0ad9ee-51fc-56a8-8920-bb28ba72a89d', $J${"source_id":"ek_anpassung_angepasstheit__funktion_von_merkmalen","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_anpassung_angepasstheit__funktion_von_merkmalen","german_label":"Funktion von Merkmalen","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Funktion von Merkmalen\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('c6ac179e-564f-510b-9da0-2f2cacafaeed', v_project, v_branch, 'concept', $J$Exaptation (traits taking on a new function)$J$, $J$A trait that arose for another function (or for none) and later took on a new function. English name drafted from the German concept "Exaptation (Umfunktionieren von Merkmalen)". LLM synthesized draft, awaiting review.$J$, '2c0ad9ee-51fc-56a8-8920-bb28ba72a89d', $J${"source_id":"ek_anpassung_angepasstheit__exaptation","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_anpassung_angepasstheit__exaptation","german_label":"Exaptation (Umfunktionieren von Merkmalen)","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Exaptation (Umfunktionieren von Merkmalen)\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('464334b6-3b5e-54e3-b2dd-ffee5bab86b4', v_project, v_branch, 'concept', $J$Evolutionary mismatch$J$, $J$An adaptation no longer fits the current environment because the environment changed faster than the adaptation could, for example through cultural change. English name drafted from the German concept "Evolutionäres Mismatch". LLM synthesized draft, awaiting review.$J$, '2c0ad9ee-51fc-56a8-8920-bb28ba72a89d', $J${"source_id":"ek_anpassung_angepasstheit__evolutionaeres_mismatch","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_anpassung_angepasstheit__evolutionaeres_mismatch","german_label":"Evolutionäres Mismatch","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Evolutionäres Mismatch\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('4b40aae2-9441-53ac-a0ce-96fab8b24382', v_project, v_branch, 'concept', $J$Domestication$J$, $J$A special case of coevolution in which people steer the evolution of crops and domestic animals through deliberate or unintended artificial selection. English name drafted from the German concept "Domestikation". LLM synthesized draft, awaiting review.$J$, 'cf023031-cec7-56dd-a042-97604581ec15', $J${"source_id":"ek_koevolution__domestikation","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_koevolution__domestikation","german_label":"Domestikation","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Domestikation\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('ea112fd0-60b9-5561-92d3-6150655435ca', v_project, v_branch, 'concept', $J$Endosymbiont theory$J$, $J$Theory that mitochondria and chloroplasts descend from free-living bacteria that were taken up by ancestors of cells with a nucleus and became organelles. English name drafted from the German concept "Endosymbiontentheorie". LLM synthesized draft, awaiting review.$J$, 'c29104e2-be2e-5fbd-b86d-f13f1a1f2b37', $J${"source_id":"ek_multilevel_selektion__endosymbiontentheorie","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_multilevel_selektion__endosymbiontentheorie","german_label":"Endosymbiontentheorie","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Endosymbiontentheorie\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('ee99ad99-85a2-5fe6-9782-ef48c35f2e8b', v_project, v_branch, 'concept', $J$Evolution from single cells to multicellular life$J$, $J$The transition from single-celled to multicellular organisms with specialized, cooperating cells. It happened several times independently. English name drafted from the German concept "Evolution von Einzellern zu Vielzellern". LLM synthesized draft, awaiting review.$J$, 'c29104e2-be2e-5fbd-b86d-f13f1a1f2b37', $J${"source_id":"ek_multilevel_selektion__einzeller_vielzeller","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_multilevel_selektion__einzeller_vielzeller","german_label":"Evolution von Einzellern zu Vielzellern","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Evolution von Einzellern zu Vielzellern\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('8259b20a-64ad-5829-9e81-3dcca72cc4ed', v_project, v_branch, 'concept', $J$Kin selection$J$, $J$Selection that favors helping genetic relatives, because helping them passes on copies of one's own genes (relatedness times benefit greater than cost). English name drafted from the German concept "Verwandtenselektion". LLM synthesized draft, awaiting review.$J$, 'c29104e2-be2e-5fbd-b86d-f13f1a1f2b37', $J${"source_id":"ek_multilevel_selektion__verwandtenselektion","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_multilevel_selektion__verwandtenselektion","german_label":"Verwandtenselektion","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Verwandtenselektion\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('b867f648-1c15-53fb-9487-27ffe61a4cef', v_project, v_branch, 'concept', $J$Evolution of cooperation and altruism$J$, $J$Explanation of how cooperative and seemingly selfless behavior can arise and stay stable through selection despite its cost to the individual. English name drafted from the German concept "Evolution von Kooperation/Altruismus". LLM synthesized draft, awaiting review.$J$, 'c29104e2-be2e-5fbd-b86d-f13f1a1f2b37', $J${"source_id":"ek_multilevel_selektion__kooperation_altruismus","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_multilevel_selektion__kooperation_altruismus","german_label":"Evolution von Kooperation/Altruismus","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Evolution von Kooperation/Altruismus\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('7c99ac31-8914-5b2d-8ee4-da755fd292d4', v_project, v_branch, 'concept', $J$Evolutionary processes within organisms$J$, $J$Selection-like processes between cells or cell lines inside one organism. English name drafted from the German concept "Evolutionäre Prozesse innerhalb von Organismen". LLM synthesized draft, awaiting review.$J$, 'c29104e2-be2e-5fbd-b86d-f13f1a1f2b37', $J${"source_id":"ek_multilevel_selektion__prozesse_innerhalb_organismen","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_multilevel_selektion__prozesse_innerhalb_organismen","german_label":"Evolutionäre Prozesse innerhalb von Organismen","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Evolutionäre Prozesse innerhalb von Organismen\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('89dccb63-86d1-5dac-887d-84eced6bd81d', v_project, v_branch, 'concept', $J$Geological epochs$J$, $J$The division of Earth history into time spans (for example Cambrian, Cretaceous, Cenozoic) that give a frame for placing evolutionary events. English name drafted from the German concept "geologische Epochen". LLM synthesized draft, awaiting review.$J$, '6829faa3-1dcc-58ac-b0c4-e99af789b71a', $J${"source_id":"ek_tiefenzeit__geologische_epochen","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_tiefenzeit__geologische_epochen","german_label":"geologische Epochen","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"geologische Epochen\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('4023b3f7-0aed-53db-b2d3-b214aa503d36', v_project, v_branch, 'concept', $J$Fossils$J$, $J$Preserved remains or traces of past organisms. They are direct material evidence for the history of life and how it changed over time. English name drafted from the German concept "Fossilien". LLM synthesized draft, awaiting review.$J$, '6829faa3-1dcc-58ac-b0c4-e99af789b71a', $J${"source_id":"ek_tiefenzeit__fossilien","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_tiefenzeit__fossilien","german_label":"Fossilien","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Fossilien\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('4af1115f-55b4-53e5-8bf4-23a9d29da1ab', v_project, v_branch, 'concept', $J$Transitional forms and lineages$J$, $J$Fossils that combine traits of an ancestral group and a descendant group and so show gradual evolutionary transitions. English name drafted from the German concept "Übergangsformen/Entwicklungslinien". LLM synthesized draft, awaiting review.$J$, '6829faa3-1dcc-58ac-b0c4-e99af789b71a', $J${"source_id":"ek_tiefenzeit__uebergangsformen","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_tiefenzeit__uebergangsformen","german_label":"Übergangsformen/Entwicklungslinien","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"Übergangsformen/Entwicklungslinien\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('852cb59b-7135-5056-a3e7-cbf9189d8874', v_project, v_branch, 'concept', $J$Common descent and relatedness$J$, $J$The basic principle that all living species descend from common ancestors and so are linked in a single branching tree of life. English name drafted from the German concept "gemeinsame Abstammung/Verwandtschaft". LLM synthesized draft, awaiting review.$J$, '7ab7367c-efc5-55db-921f-2ac8cd8e471a', $J${"source_id":"ek_stammbaeume_phylogenetik__gemeinsame_abstammung","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_stammbaeume_phylogenetik__gemeinsame_abstammung","german_label":"gemeinsame Abstammung/Verwandtschaft","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"gemeinsame Abstammung/Verwandtschaft\" in the Thuringia space."}}$J$::jsonb, 'proposed'),
  ('a9caad0b-d703-5689-84f3-09407644bdab', v_project, v_branch, 'concept', $J$Biogenetic law$J$, $J$Haeckel's historical claim that the development of an individual repeats the evolutionary history of its group. In this strict form it has been refuted. Modern evo-devo replaces it with the idea of shared but modified developmental programs. English name drafted from the German concept "biogenetische Grundregel". LLM synthesized draft, awaiting review.$J$, 'f1c3628c-6133-5771-8f26-b3da50b4cfed', $J${"source_id":"ek_evo_devo__biogenetische_grundregel","vocabulary":"EVOMENTOR-US-PREVIEW","origin":"translated-from-evomentor-de","kind":"evolution-concept","german_id":"ek_evo_devo__biogenetische_grundregel","german_label":"biogenetische Grundregel","level":2,"review":{"state":"unreviewed","tag":"LLM synthesized draft, awaiting review"},"proposed_extension":{"draft_note":"LLM synthesized draft, awaiting review. English name drafted from the German concept \"biogenetische Grundregel\" in the Thuringia space."}}$J$::jsonb, 'proposed')
  INSERT INTO lpm_data_objects (id, project_id, branch_id, object_type, title, description, grade_band, subject_area, content, status, curriculum_sequence) VALUES
  ('423c564d-cbb3-5c1d-be94-5fd67cb5dc57', v_project, v_branch, 'performance_indicator', $J$1-LS3-1 · Offspring look like their parents but differ$J$, $J$Make observations to construct an evidence-based account that young plants and animals are like, but not exactly like, their parents.$J$, $J$1$J$, 'Science', $J${"source_id":"NGSS 1-LS3-1","code":"1-LS3-1","thema":"Heredity: Inheritance and Variation of Traits","unterthema":"LS3.A: Inheritance of Traits; LS3.B: Variation of Traits","ngssBand":"K-2","gradeLabel":"Grade 1","concepts":[{"id":"ngss-ccc-patterns","label":"Patterns","emphasis":"primary"}],"foundationBox":{"practices":["Constructing Explanations and Designing Solutions"],"coreIdeas":["LS3.A: Inheritance of Traits","LS3.B: Variation of Traits"],"crosscuttingConcepts":["Patterns"]},"evolutionRelevance":{"level":2,"label":"Covers the idea without the word","why":"Young organisms look like their parents but differ in small ways. That is inheritance and variation, two things evolution needs. The text does not mention evolution.","concepts":["Inheritance of traits","Variation and diversity"],"germanConcepts":["Vererbung von Merkmalen","Variation und Diversität"]},"basiskonzeptbezug":[{"basiskonzept_id":"e4a76f03-c5c7-567c-ba76-3deaad6c5dc1","conceptName":"Patterns","relevanz_beurteilung":3,"begruendung":"Named as a crosscutting concept in the NGSS foundation box of this expectation.","relevante_unterkonzepte_taxonomie":[{"value":"Patterns","taxonomyElementId":"e4a76f03-c5c7-567c-ba76-3deaad6c5dc1"}],"basis":"ngss-foundation-box","draftTag":"LLM synthesized draft, awaiting review"},{"basiskonzept_id":"10dbf53a-e6bf-59ac-a274-9f4512e8392a","conceptName":"Evolution concepts","relevanz_beurteilung":2,"begruendung":"Young organisms look like their parents but differ in small ways. That is inheritance and variation, two things evolution needs. The text does not mention evolution.","relevante_evolutionskonzepte":["Inheritance of traits","Variation and diversity"],"rel