  ('c4973582-4c1c-5bf9-8070-41a2e5421b5e', v_project, v_branch, 'performance_indicator', $J$2-LS4-1 · Compare the diversity of life in habitats$J$, $J$Make observations of plants and animals to compare the diversity of life in different habitats.$J$, $J$2$J$, 'Science', $J${"source_id":"NGSS 2-LS4-1","code":"2-LS4-1","thema":"Biological Evolution: Unity and Diversity","unterthema":"LS4.D: Biodiversity and Humans","ngssBand":"K-2","gradeLabel":"Grade 2","concepts":[],"foundationBox":{"practices":["Planning and Carrying Out Investigations"],"coreIdeas":["LS4.D: Biodiversity and Humans"],"crosscuttingConcepts":[]},"evolutionRelevance":{"level":1,"label":"Background only","why":"Students compare how many kinds of life live in different habitats. This is background for later work on diversity and adaptation. The text says nothing about change over generations.","concepts":["Variation and diversity"],"germanConcepts":["Variation und Diversität"]},"basiskonzeptbezug":[{"basiskonzept_id":"10dbf53a-e6bf-59ac-a274-9f4512e8392a","conceptName":"Evolution concepts","relevanz_beurteilung":1,"begruendung":"Students compare how many kinds of life live in different habitats. This is background for later work on diversity and adaptation. The text says nothing about change over generations.","relevante_evolutionskonzepte":["Variation and diversity"],"relevante_evolutionskonzepte_taxonomie":[{"value":"Variation and diversity","taxonomyElementId":"558ae4ad-88ed-55fb-af95-6084100d35d3"}],"basis":"llm-judgment","draftTag":"LLM synthesized draft, awaiting review"}],"shortLabelNote":"The short label after the code is ours. The expectation text is NGSS.","textCheck":{"reads":2,"note":"Text read from nextgenscience.org on 2026-11-13 through a page-summarizing fetch tool. It has not been compared with the printed standards."},"attribution":"Text of the expectation: NGSS Lead States. 2013. Next Generation Science Standards: For States, By States. Washington, DC: The National Academies Press. Used under the NGSS Public License (https://www.nextgenscience.org/ngss-trademarks-and-copyright/ngss-trademarks-and-copyright).","draftTag":"LLM synthesized draft, awaiting review","review":{"state":"unreviewed","note":"Evolution level, concept tags and links were drafted by an LLM from the expectation text and its foundation box. No expert has reviewed them."},"_source":{"repo":"NGSS Lead States (2013), nextgenscience.org","path":"https://www.nextgenscience.org/pe/2-ls4-1-biological-evolution-unity-and-diversity"}}$J$::jsonb, 'accepted', 2),
  ('925066b3-c513-5ae3-b36a-a82ef67a4bde', v_project, v_branch, 'performance_indicator', $J$3-LS2-1 · Group living helps animals survive$J$, $J$Construct an argument that some animals form groups that help members survive.$J$, $J$3$J$, 'Science', $J${"source_id":"NGSS 3-LS2-1","code":"3-LS2-1","thema":"Ecosystems: Interactions, Energy, and Dynamics","unterthema":"LS2.D: Social Interactions and Group Behavior","ngssBand":"3-5","gradeLabel":"Grade 3","concepts":[{"id":"ngss-ccc-cause-and-effect","label":"Cause and Effect","emphasis":"primary"}],"foundationBox":{"practices":["Engaging in Argument from Evidence"],"coreIdeas":["LS2.D: Social Interactions and Group Behavior"],"crosscuttingConcepts":["Cause and Effect"]},"evolutionRelevance":{"level":2,"label":"Covers the idea without the word","why":"Group living helps members survive. The benefits of living in groups are one starting point for the evolution of cooperation. The text does not mention evolution.","concepts":["Evolution of cooperation and altruism","Function of traits"],"germanConcepts":["Evolution von Kooperation/Altruismus","Funktion von Merkmalen"]},"basiskonzeptbezug":[{"basiskonzept_id":"b23510e6-ff1d-5529-969e-ef072243ffbb","conceptName":"Cause and Effect","relevanz_beurteilung":3,"begruendung":"Named as a crosscutting concept in the NGSS foundation box of this expectation.","relevante_unterkonzepte_taxonomie":[{"value":"Cause and Effect","taxonomyElementId":"b23510e6-ff1d-5529-969e-ef072243ffbb"}],"basis":"ngss-foundation-box","draftTag":"LLM synthesized draft, awaiting review"},{"basiskonzept_id":"10dbf53a-e6bf-59ac-a274-9f4512e8392a","conceptName":"Evolution concepts","relevanz_beurteilung":2,"begruendung":"Group living helps members survive. The benefits of living in groups are one starting point for the evolution of cooperation. The text does not mention evolution.","relevante_evolutionskonzepte":["Evolution of cooperation and altruism","Function of traits"],"relevante_evolutionskonzepte_taxonomie