  ('95ea2703-3c1d-522f-a1fc-4bc0196b2130', v_project, v_branch, 'performance_indicator', $J$3-LS3-1 · Traits are inherited and vary within a group$J$, $J$Analyze and interpret data to provide evidence that plants and animals have traits inherited from parents and that variation of these traits exists in a group of similar organisms.$J$, $J$3$J$, 'Science', $J${"source_id":"NGSS 3-LS3-1","code":"3-LS3-1","thema":"Heredity: Inheritance and Variation of Traits","unterthema":"LS3.A: Inheritance of Traits; LS3.B: Variation of Traits","ngssBand":"3-5","gradeLabel":"Grade 3","concepts":[{"id":"ngss-ccc-patterns","label":"Patterns","emphasis":"primary"}],"foundationBox":{"practices":["Analyzing and Interpreting Data"],"coreIdeas":["LS3.A: Inheritance of Traits","LS3.B: Variation of Traits"],"crosscuttingConcepts":["Patterns"]},"evolutionRelevance":{"level":2,"label":"Covers the idea without the word","why":"Students find that traits are inherited and that individuals in a group vary. Inheritance and variation are two of the conditions for natural selection. The text does not mention evolution.","concepts":["Inheritance of traits","Phenotypic variation"],"germanConcepts":["Vererbung von Merkmalen","phänotypische Variation"]},"basiskonzeptbezug":[{"basiskonzept_id":"e4a76f03-c5c7-567c-ba76-3deaad6c5dc1","conceptName":"Patterns","relevanz_beurteilung":3,"begruendung":"Named as a crosscutting concept in the NGSS foundation box of this expectation.","relevante_unterkonzepte_taxonomie":[{"value":"Patterns","taxonomyElementId":"e4a76f03-c5c7-567c-ba76-3deaad6c5dc1"}],"basis":"ngss-foundation-box","draftTag":"LLM synthesized draft, awaiting review"},{"basiskonzept_id":"10dbf53a-e6bf-59ac-a274-9f4512e8392a","conceptName":"Evolution concepts","relevanz_beurteilung":2,"begruendung":"Students find that traits are inherited and that individuals in a group vary. Inheritance and variation are two of the conditions for natural selection. The text does not mention evolution.","relevante_evolutionskonzepte":["Inheritance of traits","Phenotypic variation"],"relevante_evolutionskonzepte_taxonomie":[{"value":"Inheritance of traits","taxonomyElementId":"b9191283-dba0-550d-8736-0d1f1f3a309d"},{"value":"Phenotypic variation","taxonomyElementId":"f6b8649b-89c4-5581-9e41-cbaeb30e0908"}],"basis":"llm-judgment","draftTag":"LLM synthesized draft, awaiting review"}],"shortLabelNote":"The short label after the code is ours. The expectation text is NGSS.","textCheck":{"reads":2,"note":"Text read from nextgenscience.org on 2026-11-13 through a page-summarizing fetch tool. It has not been compared with the printed standards."},"attribution":"Text of the expectation: NGSS Lead States. 2013. Next Generation Science Standards: For States, By States. Washington, DC: The National Academies Press. Used under the NGSS Public License (https://www.nextgenscience.org/ngss-trademarks-and-copyright/ngss-trademarks-and-copyright).","draftTag":"LLM synthesized draft, awaiting review","review":{"state":"unreviewed","note":"Evolution level, concept tags and links were drafted by an LLM from the expectation text and its foundation box. No expert has reviewed them."},"_source":{"repo":"NGSS Lead States (2013), nextgenscience.org","path":"https://www.nextgenscience.org/pe/3-ls3-1-heredity-inheritance-and-variation-traits"}}$J$::jsonb, 'accepted', 4),
  ('d3b82d69-0eed-50fc-bb15-297e87bcb648', v_project, v_branch, 'performance_indicator', $J$3-LS3-2 · The environment can shape traits$J$, $J$Use evidence to support the explanation that traits can be influenced by the environment.$J$, $J$3$J$, 'Science', $J${"source_id":"NGSS 3-LS3-2","code":"3-LS3-2","thema":"Heredity: Inheritance and Variation of Traits","unterthema":"LS3.A: Inheritance of Traits; LS3.B: Variation of Traits","ngssBand":"3-5","gradeLabel":"Grade 3","concepts":[{"id":"ngss-ccc-cause-and-effect","label":"Cause and Effect","emphasis":"primary"}],"foundationBox":{"practices":["Constructing Explanations and Designing Solutions"],"coreIdeas":["LS3.A: Inheritance of Traits","LS3.B: Variation of Traits"],"crosscuttingConcepts":["Cause and Effect"]},"evolutionRelevance":{"level":2,"label":"Covers the idea without the word","why":"Students see that the environment can shape a trait. This helps separate inherited variation from changes caused by the environment, a common point of confusion in evolution teaching. The text does not mention evolution.","concepts":["Modification","Phenotypic plasticity"],"germanConcepts":["Modifikation","Phänotypische Plastizität"]},"basiskonzeptbezug":[{"basiskonzept_id":"b23510e6-ff1d-5529-969e-ef072243ffbb","conceptName":"Cause and Effect","relevanz_beurteilung":3,"begruendung":"Named as a crosscutting concept in the NGSS foundation box of this expectation.","relevante_unterkonzepte_taxonomie":[{"value":"Cause and Effect","taxonomyElementId":"b23510e6-ff1d-5529-969e-ef072243ffbb"}],"basis":"ngss-foundation-box","draftTag":"LLM synthesized draft, awaiting review"},{"basiskonzept_id":"10dbf53a-e6bf-59ac-a274-9f4512e8392a","conceptName":"Evolution concepts","relevanz_beurteilung":2,"begruendung":"Students see that the environment can shape a trait. This helps separate inherited variation from changes caused by the environment, a common point of confusion in evolution teaching. The text does not mention evolution.","relevante_evo